def blocks(grid, color):
    # 3x3 solid squares of given color; return top-left (r,c)
    out=[]
    for r in range(len(grid)-2):
        for c in range(len(grid[0])-2):
            if all(grid[r+i][c+j]==color for i in range(3) for j in range(3)):
                out.append((r,c))
