def solve(k):
    i=np.array(G[k+' input']); o=np.array(G[k+' output'])
    cnt=Counter(i.flatten()); bkg=int(cnt.most_common(1)[0][0])
    others={v:int(v) for v in set(i.flatten())-{bkg}}
    # object = largest total area among colors; dots = remaining
    sizes={}
    for v in others:
        s=(i==v).sum()
        sizes[v]=s
    objc=max(sizes,key=sizes.get); dotc=min(sizes,key=sizes.get)
    mask=i==objc
    H,W=i.shape
    cells=np.argwhere(mask); rs_,cs_=cells.min(axis=0); r2_,c2_=cells.max(axis=0)
    bh=r2_-rs_+1; bw=c2_-cs_+1; oh,ow=o.shape
    pred=bkg*np.ones_like(o,int)
    for j in range(oh):
        for kc in range(ow):
            rr0=int(rs_+j*bh/oh); cc0=int(cs_+kc*bw/ow)
            rr1=int(rs_+(j+1)*bh/oh); cc1=int(cs_+(kc+1)*bw/ow)
            blk=mask[int(rr0):min(int(rr1),H), int(cc0):min(int(cc1),W)]
            dotset=(i==dotc)[int(rr0):int(rr1), int(cc0):int(cc1)]
            if (blk.any()):
                adj=(dotset & (np.pad(dotset.astype(bool),(1,1,1,1))>0)).sum()
                # dot inside block adjacent to object
                # find dot cells and check neighbors are obj
                dr,dc=np.where(dotset)
                found=False
                for a,b in zip(dr,dc):
                    for da,db in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=da<H and 0<=db<W and mask[da,db]:
                            found=True;break
                    if found:break
                if found:
                    pred[j,kc]=dotc
    return (pred==o).all(), pred.tolist()
