            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps_of(i,v):
    H,W=i.shape; seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if i[r,c]==v and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); s=[]
                while q:
                    a,b=q.popleft(); s.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and i[x,y]==v and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                out.append(s)
    return out

def solve_rule(k, variant):
    i=np.array(G[k+' input']); o=np.array(G[k+' output'])
    cnt=Counter(i.flatten()); bkg=cnt.most_common(1)[0][0]
    others={v:c for v,c in cnt.items() if v!=bkg}
    objcol=max(others,key=lambda v:others[v]); dotcol=min(set(i.flatten())-{bkg,objcol})
    oh,ow=o.shape
    H,W=i.shape
    hs=int(np.ceil(H/oh)); ws=int(np.ceil(W/ow))
    out=[]
    for j in range(oh):
        row=[]
        for kc in range(ow):
            blk=i[j*hs:(j+1)*hs,kc*ws:(kc+1)*ws]
            ds=comps_of(blk,dotcol); os_=comps_of(blk,objcol)
            nd=sum(len(s) for s in ds)
            dopts=len([s for s in ds if len(s)==1])
            objs=len(os_)
            # compute per-tile: does tile contain a 2x2 solid block of obj?
            B,C=blk.shape; has22=False
            for r in range(B-1):
                for c in range(C-1):
                    if blk[r,c]==objcol and blk[r,c+1]==objcol and blk[r+1,c]==objcol and blk[r+1,c+1]==objcol:
                        has22=True; break
                if has22: break
            # variant A: marked iff any dot (anywhere in input) orthogonally/tangentially adjacent to an object cell
            if variant=='A':
                row.append(dotcol if any(p in ds or True for ds_local in ds for p in ds_local) else bkg)
            elif variant=='B':
                # dot cell inside tile adjacent (ortho OR diag) to object cell inside tile
                B_,C_=blk.shape
                row.append(dotcol if any((0<=da<B_ and 0<=db<C_ and blk[da,db]==objcol) 
                           for a,b in [p for s in ds for p in s] for da,db in ((a+1,b),(a-1,b),(a,b+1),(a,b-1),(a+1,b+1),(a+1,b-1),(a-1,b+1),(a-1,b-1))) else bkg)
            elif variant=='C':
                row.append(dotcol if has22 else bkg)
            elif variant=='D':
                # tile contains any object cell AND any dot cell
                row.append(dotcol if sum(b==dotcol for b in blk.flatten())>0 and any(b==objcol for b in blk.flatten())>0 else bkg)
            elif variant=='E':
                row.append(dotcol if nd>0 else bkg)
            elif variant=='F':
                row.append(dotcol if objs>0 else bkg)
            out.append(row)
        return np.array(out).tolist()

for k in ['Demo pair 5','Demo pair 7','Demo pair 8']:
    exp=np.array(G[k+' output'])
    for var in ['A','B','C','D','E','F']:
        p=solve_rule(k,var)
        print(k,var,'match:',np.array(p).tolist()==exp.tolist())

