            B_,C_=blk.shape
            if rule=='A':# any dot orthogonally adjacent to an object cell INSIDE tile
                marked=False
                for a,b in [(a,b) for s in comps_of(blk,dotcol) for a,b in s]:
                    for da,db in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=da<B_ and 0<=db<C_ and blk[da,db]==objcol:
                            marked=True; break
                    if marked: break
                row.append(dotcol if marked else bkg)
            elif rule=='B':# full 2x2 solid obj block inside tile
                has22=False
                for r in range(B_-1):
                    for c in range(C_-1):
                        if blk[r,c]==objcol and blk[r,c+1]==objcol and blk[r+1,c]==objcol and blk[r+1,c+1]==objcol:
                            has22=True; break
                    if has22: break
                row.append(dotcol if has22 else bkg)
            elif rule=='C':# dot cell inside tile adjacent to object cell in the whole grid
                marked=False
                for a,b in [(a,b) for s in comps_of(blk,dotcol) for a,b in s]:
                    for da,db in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=da<H and 0<=db<W and i[da,db]==objcol:
                            marked=True; break
                    if marked: break
                row.append(dotcol if marked else bkg)
            elif rule=='D':# 2x2 block containing both dot and object pixels (mixed)
                marked=False
                for r in range(B_):
                    for c in range(C_):
                        sub=blk[r:r+2,c:c+2]
                        if len(sub.flatten())>=4 and sum(sub==dotcol)>0 and sum(sub==objcol)>0:
                            marked=True; break
                    if marked: break
                row.append(dotcol if marked else bkg)
            out.append(row)
        return np.array(out).tolist()
